            A("tray.exit", "Sair", "Exit");
            A("tray.hint.title", "ro0tLimiter continua na bandeja", "ro0tLimiter is still in the tray");
            A("tray.hint.service", "As regras continuam sendo aplicadas pelo serviço.", "Rules keep being enforced by the service.");
            A("tray.hint.local", "O controle continua ativo. Use Sair no menu do ícone para encerrar.", "Filtering stays on. Use Exit on the icon menu to quit.");
            A("mode.service", "Service Mode: Active", "Service Mode: Active");
            A("mode.local", "Local Mode: Active", "Local Mode: Active");
            A("mode.service.tip", "O serviço do Windows aplica as regras desde a inicialização, mesmo com o app fechado.", "The Windows service applies the rules from startup, even with the app closed.");
            A("mode.service.help", "O serviço do Windows aplica as regras desde a inicialização, mesmo com o app fechado.\n\n• Os limites e os bloqueios continuam valendo depois que você fecha o ro0tLimiter.\n• O serviço precisa estar instalado e em execução.\n• Você instala o serviço pelo botão Serviço, na janela principal.", "The Windows service applies the rules from startup, even with the app closed.\n\n• Limits and blocks keep working after you close ro0tLimiter.\n• The service has to be installed and running.\n• You install the service from the Service button on the main window.");
            A("mode.local.tip", "As regras valem enquanto o ro0tLimiter estiver aberto ou na bandeja.", "Rules apply while ro0tLimiter is open or in the tray.");
            A("mode.local.help", "As regras valem enquanto o ro0tLimiter estiver aberto ou na bandeja.\n\nFechar o programa para o limitador. Nada fica aplicado entre um início do Windows e a próxima vez que você abrir o ro0tLimiter.", "Rules apply while ro0tLimiter is open or in the tray.\n\nClosing the program stops the limiter. Nothing stays applied between a Windows start and the next time you open ro0tLimiter.");
            A("status.stopped", "Parado — o tráfego não está sendo monitorado nem controlado", "Stopped — traffic is not being monitored or controlled");
            A("status.running", "Ativo — o tráfego está sendo interceptado", "Running — traffic is being intercepted");
            A("status.manual", "Pronto — o filtro não inicia sozinho (veja Configurações)", "Ready — filtering does not start on its own (see Settings)");
            A("svc.missing", "Serviço: não instalado", "Service: not installed");
